    @Test
    void energyDensityRegistrationValidationAndIdempotency() throws Exception {
        String p = prefix();
        postJson("/api/assets", Map.of("id", p + "movie", "durationMs", 3600000))
                .andExpect(status().isOk());

        // 400：超过 10 / 小数超过 3 位 / 负数 / 缺操作者
