        // 新 requestId 重复登记：409，登记后不可修改
        registerDensity(p + "movie", "req-" + p + "-again", "tester", new BigDecimal("6"))
                .andExpect(status().isConflict())
                .andExpect(jsonPath("$.error").value("ENERGY_DENSITY_ALREADY_REGISTERED"));
    }
